// Series: Any single component failure takes down the request path
export function calculateSeriesAvailability(availabilities: number[]): number {
  return availabilities.reduce((acc, curr) => acc * curr, 1);
}

// Parallel: The path stays available unless ALL redundant replicas fail
export function calculateParallelAvailability(replicaAvailability: number, replicaCount: number): number {
  const failureProb = 1 - replicaAvailability;
  return 1 - Math.pow(failureProb, replicaCount);
}

// Two 99.9% nodes in parallel yield 99.9999% (Six Nines)!
